@@ -0,0 +1,86 @@
+import test from "node:test";
+import assert from "node:assert/strict";
+import { app } from "./helpers.js";
+
+const ANNEX = { "X-Larder-Site": "annex" };
+
+// Puts 5 kg of flour (item 4) into the annex fridge through an order.
+async function stockAnnex(handle) {
+  const order = (await handle({ method: "POST", path: "/orders", body: { supplierId: 1, lines: [{ itemId: 4, qty: 5 }] } })).body;
+  await handle({ method: "POST", path: `/orders/${order.id}/send` });
+  return handle({ method: "POST", path: `/orders/${order.id}/receive`, headers: ANNEX, body: { lots: [{ lot: "AX-1", expires: "2026-10-30", location: "annex-fridge" }] } });
+}
+
+test("without the header the site is main", async () => {
+  const { handle } = app();
+  const items = (await handle({ path: "/items" })).body;
+  assert.equal(items.find((i) => i.id === 1).onHand, 10);
+});
+
+test("an unknown site is a 400 with its own code", async () => {
+  const { handle } = app();
+  const res = await handle({ path: "/items", headers: { "x-larder-site": "attic" } });
+  assert.equal(res.status, 400);
+  assert.equal(res.body.error.code, "unknown_site");
+  assert.match(res.body.error.message, /attic/);
+});
+
+test("each site sees only its own stock", async () => {
+  const { handle } = app();
+  assert.equal((await stockAnnex(handle)).status, 200);
+  const annexItems = (await handle({ path: "/items", headers: ANNEX })).body;
+  assert.equal(annexItems.find((i) => i.id === 4).onHand, 5);
+  assert.equal(annexItems.find((i) => i.id === 1).onHand, 0);
+  const mainItems = (await handle({ path: "/items" })).body;
+  assert.equal(mainItems.find((i) => i.id === 4).onHand, 12.5);
+  const annexBatches = (await handle({ path: "/batches", headers: ANNEX })).body;
+  assert.deepEqual(annexBatches.map((b) => b.lot), ["AX-1"]);
+  assert.equal((await handle({ path: "/batches/1", headers: ANNEX })).status, 404);
+  assert.equal((await handle({ path: `/batches/${annexBatches[0].id}` })).status, 404);
+  const value = (await handle({ path: "/reports/stock-value", headers: ANNEX })).body;
+  assert.equal(value.totalCents, 5 * 85);
+  const alerts = (await handle({ path: "/alerts", headers: ANNEX })).body;
+  assert.deepEqual(alerts.expiring.map((b) => b.lot), ["AX-1"]);
+  assert.ok(alerts.lowStock.some((i) => i.name === "onion"));
+});
+
+test("receiving goes to a location of the request's site", async () => {
+  const { handle } = app();
+  const order = (await handle({ method: "POST", path: "/orders", body: { supplierId: 1, lines: [{ itemId: 4, qty: 5 }] } })).body;
+  await handle({ method: "POST", path: `/orders/${order.id}/send` });
+  const res = await handle({ method: "POST", path: `/orders/${order.id}/receive`, body: { lots: [{ lot: "X", expires: null, location: "annex-fridge" }] } });
+  assert.equal(res.status, 400);
+  assert.equal(res.body.error.code, "unknown_location");
+});
+
+test("cooking uses only the request's site", async () => {
+  const { handle, store } = app();
+  const before = JSON.stringify(store.data.batches);
+  const res = await handle({ method: "POST", path: "/recipes/1/cook", headers: ANNEX, body: { portions: 1 } });
+  assert.equal(res.status, 409);
+  assert.equal(JSON.stringify(store.data.batches), before);
+});
+
+test("stock-takes stay within their site", async () => {
+  const { handle } = app();
+  assert.equal((await handle({ method: "POST", path: "/stocktakes", headers: ANNEX, body: { location: "dry" } })).status, 400);
+  const take = (await handle({ method: "POST", path: "/stocktakes", body: { location: "dry" } })).body;
+  assert.equal((await handle({ method: "POST", path: `/stocktakes/${take.id}/finish`, headers: ANNEX })).status, 404);
+  const annexTake = await handle({ method: "POST", path: "/stocktakes", headers: ANNEX, body: { location: "annex-fridge" } });
+  assert.equal(annexTake.status, 201);
+  const count = await handle({ method: "POST", path: `/stocktakes/${annexTake.body.id}/counts`, headers: ANNEX, body: { batchId: 6, counted: 1 } });
+  assert.equal(count.status, 404);
+});
+
+test("the nightly job checks every site", async () => {
+  const { handle, store } = app();
+  await stockAnnex(handle);
+  await handle({ method: "POST", path: "/jobs/nightly" });
+  const keys = store.data.outbox.map((m) => m.key);
+  assert.ok(!keys.includes("low:2026-10-28"));
+  assert.ok(keys.includes("low:annex:2026-10-28"));
+  assert.ok(keys.some((k) => k.startsWith("expiry:2026-10-28:")));
+  const n = store.data.outbox.length;
+  await handle({ method: "POST", path: "/jobs/nightly" });
+  assert.equal(store.data.outbox.length, n);
+});
